describe('scratch', () => {
  test('sync propagation (parent not updating)', () => {
    using parent = buildEditorFromExtensions({name: 'parent'});
    const child = parent.read(() =>
      buildEditorFromExtensions({
        dependencies: [NestedEditorExtension],
        name: 'child',
      }),
    );
    const log: string[] = [];
    let parentGotEditor: LexicalEditor | null = null;
    let getEditorInParent: LexicalEditor | null = null;
